84	OrcaPrinterBackend::OrcaPrinterBackend(Plater& plater, PrinterCatalog catalog, Workspace::SpoolStore* spools)
85	    : m_plater(plater), m_catalog(std::move(catalog)), m_spools(spools)
86	{
87	    // The catalogue carries one candidate per model and nozzle; a person has
88	    // one printer with one nozzle, so fold the variants into the model and
89	    // keep the sizes it ships as a fact about it.
90	    for (const PrinterCandidate& candidate : m_catalog.candidates()) {
91	        const std::string id = candidate.vendor_id + "/" + candidate.model_id;
92	        const auto        known = std::find_if(m_models.begin(), m_models.end(),
93	                                               [&id](const CatalogPrinter& printer) { return printer.id == id; });
94	        CatalogPrinter&   printer = known == m_models.end() ? m_models.emplace_back(entry_of(candidate)) : *known;
95	        const double      nozzle  = nozzle_of(candidate.variant);
96	        if (nozzle > 0. && std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end())
97	            printer.nozzles.push_back(nozzle);
98	    }
99	    for (CatalogPrinter& printer : m_models)
100	        std::sort(printer.nozzles.begin(), printer.nozzles.end());
101	}
102	
103	std::vector<CatalogPrinter> OrcaPrinterBackend::search_catalog(const std::string& text, std::size_t limit) const
104	{
105	    const std::vector<std::string> words = words_of(text);
106	    std::vector<CatalogPrinter>    found;
107	    if (words.empty())
108	        return found;
109	
110	    for (const CatalogPrinter& printer : m_models) {
111	        if (found.size() >= limit)
112	            break;
113	        const std::string haystack =
114	            lowered(printer.vendor_name + " " + printer.model_name + " " + printer.build_volume + " " + printer.device_model_id);
115	        if (matches(haystack, words))
116	            found.push_back(printer);
117	    }
118	    return found;
119	}
120	
121	std::vector<DiscoveredPrinter> OrcaPrinterBackend::network_printers() const { return discover_printers(); }
122	
123	const CatalogPrinter* OrcaPrinterBackend::model_of(const std::string& printer_name) const
124	{
125	    const PresetBundle* presets = wxGetApp().preset_bundle;
126	    if (presets == nullptr)
127	        return nullptr;
128	    const Preset* preset = presets->printers.find_preset(printer_name, false);
129	    if (preset == nullptr)
130	        return nullptr;
131	    const std::string model = preset->config.opt_string("printer_model");
132	    const auto        found = std::find_if(m_models.begin(), m_models.end(),
133	                                           [&model](const CatalogPrinter& printer) { return printer.model_id == model; });
134	    return found == m_models.end() ? nullptr : &*found;
135	}
136	
137	std::vector<SavedPrinter> OrcaPrinterBackend::saved_printers() const
138	{
139	    const std::vector<DiscoveredPrinter> network = discover_printers(/*include_unreachable=*/true);
140	    const PresetBundle*                  presets = wxGetApp().preset_bundle;
141	
142	    std::vector<SavedPrinter> printers;
143	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
144	        SavedPrinter saved;
145	        saved.name      = named.name;
146	        saved.device_id = named.device_id;
147	        saved.nozzle    = named.nozzle;
148	
149	        if (const CatalogPrinter* model = model_of(named.name)) {
150	            saved.model     = model->vendor_name + " " + model->model_name;
151	            saved.model_id  = model->model_id;
152	            saved.vendor_id = model->vendor_id;
153	            saved.picture   = model->picture;
154	            saved.nozzles   = model->nozzles;
155	            saved.plate     = model->default_plate;
156	        }
157	        if (presets != nullptr) {
158	            if (const Preset* preset = presets->printers.find_preset(named.name, false)) {
159	                const std::string plate = preset->config.opt_string("default_bed_type");
160	                if (!plate.empty())
161	                    saved.plate = plate;
162	            }
163	        }
164	
165	        // What the machine says beats what the profile assumed.
166	        const auto found = std::find_if(network.begin(), network.end(),
167	                                        [&saved](const DiscoveredPrinter& device) { return device.stable_id == saved.device_id; });
168	        if (found != network.end() && !saved.device_id.empty()) {
169	            saved.connected = found->connected;
170	            saved.activity  = found->activity == PrinterActivity::Printing ? "printing" :
171	                              found->activity == PrinterActivity::Idle     ? "idle" :
172	                                                                            "offline";
173	            saved.ams       = found->ams_name;
174	            for (const DiscoveredPrinter::Spool& spool : found->spools)
175	                saved.spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
176	        } else if (m_spools != nullptr) {
177	            // Not connected, or never was: what this app remembers is loaded.
178	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
179	                saved.spools.push_back(PrinterSpool{spool.name, spool.filament_preset, spool.colour});
180	        }
181	        printers.push_back(std::move(saved));
182	    }
183	    return printers;
184	}
185	
186	std::string OrcaPrinterBackend::add_printer(const AddPrinterRequest& request, SavedPrinter& added)
187	{
188	    std::string error;
189	    if (!SetupCommands::install_and_select_printer(m_plater, request.vendor_id, request.model_id, request.variant,
190	                                                  request.material, error))
191	        return error.empty() ? std::string("This printer could not be installed.") : error;
192	
193	    const std::string name =
194	        Printers::add_named_printer(m_plater, request.name.empty() ? request.model_id : request.name, request.device_id);
195	
196	    if (!request.access_code.empty() && !request.device_id.empty()) {
197	        wxString connect_error;
198	        // The printer is saved either way: a code that does not take is a
199	        // connection that has to be made again, not a printer that was lost.
200	        if (!SetupCommands::set_printer_access_code(request.device_id, request.access_code, connect_error)) {
201	            for (const SavedPrinter& saved : saved_printers())
202	                if (saved.name == name)
203	                    added = saved;
204	            return connect_error.empty() ? std::string("That access code was not accepted.") : connect_error.ToStdString();
205	        }
206	    }
207	
208	    for (const SavedPrinter& saved : saved_printers())
209	        if (saved.name == name)
210	            added = saved;
211	    return {};
212	}
213	
214	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed)
215	{
216	    std::vector<SavedPrinter> printers = saved_printers();
217	    const auto                found    = std::find_if(printers.begin(), printers.end(),
218	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
219	    if (found == printers.end())
220	        return "This app no longer has a printer called \"" + request.name + "\".";
221	
222	    if (request.nozzle) {
223	        const PrinterCandidate* variant = nullptr;
224	        for (const PrinterCandidate& candidate : m_catalog.candidates())
225	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
226	                variant = &candidate;
227	        if (variant == nullptr)
228	            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
229	                                          "The " + found->model + " does not come with that nozzle size.";
230	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name);
231	        if (!problem.empty())
232	            return problem.ToStdString();
233	    }
234	
235	    if (request.spools) {
236	        if (m_spools == nullptr)
237	            return "This app cannot record spools yet.";
238	        for (const Workspace::Spool& spool : m_spools->spools_for(request.name))
239	            m_spools->remove(spool.id);
240	        for (const PrinterSpool& spool : *request.spools) {
241	            Workspace::Spool record;
242	            record.printer_preset  = request.name;
243	            record.filament_preset = spool.material;
244	            record.name            = spool.name;
245	            record.colour          = spool.colour;
246	            m_spools->add(std::move(record));
247	        }
248	    }
249	
250	    if (request.access_code) {
251	        if (found->device_id.empty())
252	            return "This printer is not one this app found on your network, so it has no access code.";
253	        wxString code_error;
254	        if (!SetupCommands::set_printer_access_code(found->device_id, *request.access_code, code_error))
255	            return code_error.empty() ? std::string("That access code was not accepted.") : code_error.ToStdString();
256	    }
257	
258	    for (const SavedPrinter& saved : saved_printers())
259	        if (saved.name == request.name)
260	            changed = saved;
261	    return {};
262	}
263	
264	void OrcaPrinterBackend::run_manual_setup()
265	{
266	    // OrcaSlicer's own printer wizard, unchanged, and the printers it
267	    // installs are saved under their own names the way the old dialog's
268	    // manual path did.
269	    const Printers::VendorMap before = wxGetApp().app_config->vendors();
270	    // False when the person closed the wizard without applying it.
271	    if (!wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS))
272	        return;
273	    Printers::name_installed_printers(m_plater, before);
274	}
275	
276	void OrcaPrinterBackend::open_printer_settings(const std::string& name)
277	{
278	    Printers::open_named_printer_settings(m_plater, name);
279	}
280	
281	} // namespace Slic3r::GUI::JusPrin::PrinterSetup
