27	
28	// What the panel asks the person about.
29	enum class ConversationMode { Add, Change };
30	
31	// One row of the pinned card. An empty value is the em dash the panel draws
32	// for a fact nobody has stated yet.
33	struct PinnedFact
34	{
35	    std::string value;
36	    // settled: known, from the printer or the person. assumed: the agent's
37	    // stated guess. changed: altered in this session, and the panel says so.
38	    std::string provenance{"settled"};
39	    std::string swatch; // "#RRGGBB" of the first loaded spool, when there is one
40	};
41	
42	// What "Add this printer" would save. Filled by printer_propose, spent by the
43	// person tapping the chip, and never by the agent.
44	struct PrinterProposal
45	{
46	    bool                valid{false};
47	    std::string         vendor_id;
48	    std::string         model_id;
49	    std::string         model_name;
50	    std::string         variant;
51	    std::string         material;
52	    std::string         device_id;
53	    std::string         picture;
54	    std::string         subline;
55	};
56	
57	// Everything the panel needs from its owner. The panel is the only
58	// implementation; the tests use a recording fake.
59	class IConversationHost
60	{
61	public:
62	    virtual ~IConversationHost() = default;
63	
64	    // A muted line in the thread, such as "Use this" · 01P00A3B.
65	    virtual void post_note(const std::string& text) = 0;
66	    // The agent answers next, with no user message in the thread: the person
67	    // tapped something rather than typing it.
68	    virtual void ask_agent(const std::string& prompt) = 0;
