170	void PrinterConversation::refresh_network()
171	{
172	    m_network = m_backend.network_printers();
173	}
174	
175	Agent::AgentSessionProfile PrinterConversation::profile() const
176	{
177	    Agent::AgentSessionProfile profile;
178	    profile.tool_names        = session_tools();
179	    // This conversation is about a machine, not about the open project.
180	    profile.include_workspace = false;
181	
182	    std::ostringstream instructions;
183	    instructions
184	        << "You are JusPrin's printer assistant, in the printer panel on the Home screen. "
185	           "Keep every turn to one or two short sentences of plain language: no lists, no headings, and never read the pinned card back. "
186	           "The panel above the thread pins four facts -- Printer, Nozzle, Plate, Filament -- and you fill them only by calling printer_propose. "
187	           "Offer what to do next with printer_suggest: up to three specific actions such as \"Use 0.3 mm layers\", never a bare Yes or No. ";
188	
189	    if (m_mode == ConversationMode::Add) {
190	        instructions
191	            << "The person is adding a printer to this app.\n"
192	               "Finding it: search the packaged profiles with printer_catalog_search using the person's own words. A photo of the printer, "
193	               "its nameplate or its box is evidence -- read it and search for what you see.\n"
194	               "One clear match: call printer_propose with that printer alone, assuming a 0.4 mm nozzle, the plate the model ships with and "
195	               "PLA unless the person or the photo says otherwise, then say in one sentence what you assumed.\n"
196	               "Two or three that fit: call printer_propose with all of them and say what tells them apart, so the person can answer.\n"
197	               "Nothing fits: say so and ask for the one detail that would settle it.\n"
198	               "The person adds the printer by tapping \"Add this printer\" on the card you drew. Never say a printer has been added, and "
199	               "never claim to have added one yourself.";
200	        if (!m_network.empty()) {
201	            instructions << "\nThese printers are on the network right now, and the panel already lists them with their own buttons, so do "
202	                            "not repeat them in your opening: ";
203	            for (const DiscoveredPrinter& found : m_network)
204	                instructions << found.name << " (" << found.stable_id << ") ";
205	        }
206	    } else {
207	        instructions << "The person already has this printer set up: " << m_printer_fact.value;
208	        if (!m_nozzle.value.empty())
209	            instructions << ", a " << m_nozzle.value << " nozzle";
210	        if (!m_plate.value.empty())
211	            instructions << ", the " << m_plate.value << " plate";
212	        if (!m_filament.value.empty())
213	            instructions << ", " << m_filament.value;
214	        instructions
215	            << (m_printer.connected ? ", connected to this app." : ", not connected to this app.")
216	            << "\nThey tell you what changed on it, or ask about it: nozzle, plate, spools, connection. Apply a change with printer_change; "
217	               "it asks the person to approve that change on a card, so say what it now is only after the result says it was applied.\n"
218	               "The plate belongs to each project rather than to the printer, so a plate change is made in the project; say so if it comes up.";
219	    }
220	    profile.instructions = instructions.str();
221	    return profile;
222	}
223	
224	std::string PrinterConversation::opening_message() const
225	{
226	    // The opening is the panel's own copy rather than a generated turn: it is
227	    // the same promise every time the panel opens, and a session that begins
228	    // with a network round trip would open on an empty thread.
229	    if (m_mode == ConversationMode::Change) {
230	        const std::string name = m_printer_fact.value.empty() ? std::string("this printer") : m_printer_fact.value;
231	        return "This is the " + name +
232	               ". Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.";
233	    }
234	    return "What printer do you have? Say it any way: \"bambu a1 mini\", \"the ender with the touchscreen\", \"not sure, the small one\".";
235	}
236	
237	json PrinterConversation::state_json() const
238	{
239	    json chips = m_chips;
240	    // The person can always add the printer the agent has drawn; the chip is
241	    // the approval for it, so it leads the row whatever else is offered.
242	    if (m_proposal.valid) {
243	        json add{{"id", "add"}, {"label", "Add this printer"}, {"style", "primary"}, {"action", "add"}};
244	        chips.insert(chips.begin(), add);
245	        chips.push_back(json{{"id", "reject"}, {"label", "Not this one"}, {"style", "plain"}, {"say", "Not this one"}});
246	    }
247	    return json{{"mode", m_mode == ConversationMode::Add ? "add" : "change"},
248	                {"caption", m_mode == ConversationMode::Add ? "NEW PRINTER" : "PRINTER"},
249	                {"facts", json{{"printer", fact_json(m_printer_fact)},
250	                               {"nozzle", fact_json(m_nozzle)},
251	                               {"plate", fact_json(m_plate)},
252	                               {"filament", fact_json(m_filament)}}},
253	                {"blocks", m_blocks},
254	                {"chips", std::move(chips)},
255	                {"chipHint", m_chip_hint},
256	                {"placeholder", m_placeholder}};
257	}
258	
259	const CatalogPrinter* PrinterConversation::catalog_entry(const std::string& id) const
260	{
261	    const auto entry = std::find_if(m_catalog.begin(), m_catalog.end(),
262	                                    [&id](const CatalogPrinter& printer) { return printer.id == id; });
263	    return entry == m_catalog.end() ? nullptr : &*entry;
264	}
265	
266	// -- The session's tools ----------------------------------------------------
267	
268	ToolExecutionCoordinator::ExtensionResult PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
269	{
270	    ToolExecutionCoordinator::ExtensionResult result;
271	    if (handler != ToolHandler::PrinterCatalogSearch && handler != ToolHandler::PrinterPropose &&
272	        handler != ToolHandler::PrinterSuggest && handler != ToolHandler::PrinterChange)
273	        return result;
274	
275	    result.handled = true;
276	    const json arguments = json::parse(activity.arguments_json, nullptr, false);
277	    if (!arguments.is_object()) {
278	        result.error = ToolError{"invalid_arguments", "The printer tool arguments are invalid."};
279	        return result;
280	    }
281	
282	    std::optional<ToolError> error;
283	    json output;
284	    switch (handler) {
285	    case ToolHandler::PrinterCatalogSearch: output = search_catalog(arguments); break;
286	    case ToolHandler::PrinterPropose: output = propose(arguments, error); break;
287	    case ToolHandler::PrinterSuggest: output = suggest(arguments); break;
288	    default: output = change(arguments, error); break;
289	    }
290	    if (error) {
291	        result.error = std::move(error);
292	        return result;
293	    }
294	    // Everything the tools draw lands in the same place: the panel's own
295	    // state, pushed once per call.
296	    if (handler != ToolHandler::PrinterCatalogSearch) {
297	        if (handler == ToolHandler::PrinterPropose && !m_blocks.empty())
298	            m_blocks.back()["afterMessageId"] = activity.correlation_id;
299	        m_host.session_changed();
300	    }
301	    result.result_json = output.dump();
302	    return result;
303	}
304	
305	json PrinterConversation::search_catalog(const json& arguments)
306	{
307	    const std::string query = arguments.value("query", std::string());
308	    const std::size_t limit = std::min<std::size_t>(arguments.value("limit", 5), 8);
309	
310	    json items = json::array();
311	    for (const CatalogPrinter& printer : m_backend.search_catalog(query, limit)) {
312	        json nozzles = json::array();
313	        for (double nozzle : printer.nozzles)
314	            nozzles.push_back(nozzle);
315	        items.push_back(json{{"catalogId", printer.id},
316	                             {"vendor", printer.vendor_name},
317	                             {"model", printer.model_name},
318	                             {"buildVolume", printer.build_volume},
319	                             {"nozzles", std::move(nozzles)},
320	                             {"plate", printer.default_plate},
321	                             {"material", printer.default_material}});
322	        if (catalog_entry(printer.id) == nullptr)
323	            m_catalog.push_back(printer);
324	    }
325	    return json{{"items", std::move(items)}};
326	}
327	
328	json PrinterConversation::propose(const json& arguments, std::optional<ToolError>& error)
329	{
330	    const json& printers = arguments.at("printers");
331	    if (printers.empty() || printers.size() > kMaximumCandidates) {
332	        error = ToolError{"invalid_arguments", "Propose one printer, or two or three when they are hard to tell apart."};
333	        return {};
334	    }
335	
336	    json cards = json::array();
337	    std::vector<const CatalogPrinter*> proposed;
338	    for (const json& entry : printers) {
339	        const std::string catalog_id = entry.value("catalogId", std::string());
340	        const std::string device_id  = entry.value("deviceId", std::string());
341	        const CatalogPrinter* known  = catalog_entry(catalog_id);
342	        if (known == nullptr) {
343	            error = ToolError{"unknown_printer",
344	                              "\"" + catalog_id + "\" is not a printer from printer_catalog_search. Search first, then propose."};
345	            return {};
346	        }
347	        proposed.push_back(known);
348	        cards.push_back(json{{"catalogId", known->id},
349	                             {"deviceId", device_id},
350	                             {"name", known->vendor_name + " " + known->model_name},
351	                             {"subline", entry.value("subline", known->build_volume)},
352	                             {"picture", picture_data_url(known->picture)},
353	                             {"action", printers.size() == 1 ? "add" : "choose"}});
354	    }
355	
356	    m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
357	                            {"seq", m_blocks.size() + 1},
358	                            {"afterMessageId", ""},
359	                            {"kind", "printers"},
360	                            {"printers", std::move(cards)}});
361	
362	    // A nozzle of zero is "nothing was said about it", which for a printer
363	    // nobody has changed is the 0.4 mm it ships with.
364	    const double      stated   = arguments.value("nozzle", 0.);
365	    const double      nozzle   = stated > 0. ? stated : 0.4;
366	    const std::string plate    = arguments.value("plate", std::string());
367	    const std::string filament = arguments.value("filament", std::string());
368	    const std::string state    = arguments.value("provenance", std::string("assumed"));
369	
370	    if (proposed.size() == 1) {
371	        const CatalogPrinter& printer = *proposed.front();
372	        const json&           entry   = printers.front();
373	        // A nozzle this model has no profile for cannot be saved, and the
374	        // person should hear that now rather than when they tap Add.
375	        if (!printer.nozzles.empty() &&
376	            std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end()) {
377	            std::string sizes;
378	            for (double size : printer.nozzles)
379	                sizes += (sizes.empty() ? "" : ", ") + nozzle_text(size);
380	            m_blocks.erase(m_blocks.end() - 1);
381	            error = ToolError{"unknown_nozzle", "The " + printer.model_name + " ships " + sizes + " nozzles, not " +
382	                                                    nozzle_text(nozzle) + "."};
383	            return {};
384	        }
385	        m_proposal = PrinterProposal{true,
386	                                     printer.vendor_id,
387	                                     printer.model_id,
388	                                     printer.vendor_name + " " + printer.model_name,
389	                                     variant_text(nozzle),
390	                                     printer.default_material,
391	                                     entry.value("deviceId", std::string()),
392	                                     printer.picture,
393	                                     entry.value("subline", printer.build_volume)};
394	        m_printer_fact = {m_proposal.model_name, "settled", {}};
395	        m_nozzle       = {nozzle_text(nozzle), state, {}};
396	        m_plate        = {plate.empty() ? printer.default_plate : plate, state, {}};
397	        m_filament     = {filament.empty() ? std::string("PLA") : filament, state, {}};
398	    } else {
399	        // Nothing is settled while two printers are still on the table.
400	        m_proposal     = {};
401	        m_printer_fact = m_nozzle = m_plate = m_filament = {};
402	    }
403	    return json{{"proposed", proposed.size()}};
404	}
405	
406	json PrinterConversation::suggest(const json& arguments)
407	{
408	    m_chips = json::array();
409	    for (const json& action : arguments.at("actions")) {
410	        const std::string label = action.value("label", std::string());
411	        if (label.empty())
412	            continue;
413	        m_chips.push_back(json{{"id", "s" + std::to_string(m_chips.size() + 1)},
414	                               {"label", label},
415	                               {"style", action.value("suggested", false) ? "suggested" : "plain"},
416	                               {"say", label}});
417	    }
418	    m_chip_hint = arguments.value("hint", std::string());
419	    return json{{"offered", m_chips.size()}};
420	}
421	
422	json PrinterConversation::change(const json& arguments, std::optional<ToolError>& error)
423	{
424	    if (m_mode != ConversationMode::Change || m_printer.name.empty()) {
425	        error = ToolError{"no_printer", "This session is not about a printer that exists yet."};
426	        return {};
427	    }
428	
429	    ChangePrinterRequest request;
430	    request.name = m_printer.name;
431	    if (arguments.contains("nozzle") && arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() > 0.)
432	        request.nozzle = arguments["nozzle"].get<double>();
433	    if (arguments.contains("accessCode") && !arguments["accessCode"].get<std::string>().empty())
434	        request.access_code = arguments["accessCode"].get<std::string>();
435	    if (arguments.contains("spools") && arguments["spools"].is_array()) {
436	        std::vector<PrinterSpool> spools;
437	        for (const json& spool : arguments["spools"])
438	            spools.push_back(PrinterSpool{spool.value("name", std::string()), spool.value("material", std::string()),
439	                                          spool.value("colour", std::string())});
440	        request.spools = std::move(spools);
441	    }
442	    if (!request.nozzle && !request.access_code && !request.spools) {
443	        error = ToolError{"nothing_to_change", "Name the nozzle, the spools or the access code that changed."};
444	        return {};
445	    }
446	
447	    SavedPrinter      changed;
448	    const std::string problem = m_backend.change_printer(request, changed);
449	    if (!problem.empty()) {
450	        error = ToolError{"change_failed", problem};
451	        return {};
452	    }
453	
454	    const double was = m_printer.nozzle;
455	    m_printer        = changed;
456	    read_saved_printer();
457	    if (request.nozzle && was != changed.nozzle)
458	        m_nozzle.provenance = "changed";
459	    if (request.spools)
460	        m_filament.provenance = "changed";
461	    m_host.printers_changed();
462	
463	    return json{{"printer", changed.name}, {"nozzle", changed.nozzle}, {"connected", changed.connected}};
464	}
465	
466	// -- Taps on the panel's own cards -------------------------------------------
467	
468	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
469	{
470	    if (type != "printer_action")
471	        return false;
472	
473	    const std::string action = payload.value("action", std::string());
474	    const std::string id     = payload.value("id", std::string());
475	    if (action == "close")
476	        m_host.close_panel();
477	    else if (action == "manual_setup") {
478	        if (m_mode == ConversationMode::Add) {
479	            // The wizard takes over from here; whatever it installed is on
480	            // the printer list the panel returns to.
481	            m_backend.run_manual_setup();
482	            m_host.printers_changed();
483	            m_host.close_panel();
484	        } else {
485	            // OrcaSlicer's own printer settings, as "Printer settings…" did
486	            // before this panel existed. It closes back into this session,
487	            // which restates the printer as it now is.
488	            m_backend.open_printer_settings(m_printer_name);
489	            read_saved_printer();
490	            m_host.printers_changed();
491	            m_host.session_changed();
492	        }
493	    } else if (action == "add")
494	        add_proposed_printer(payload.value("accessCode", std::string()));
495	    else if (action == "network_pick")
496	        use_network_printer(id);
497	    else if (action == "candidate_pick")
498	        choose_candidate(id);
499	    return true;
500	}
501	
502	void PrinterConversation::add_proposed_printer(const std::string& access_code)
503	{
504	    if (!m_proposal.valid)
505	        return;
506	
507	    AddPrinterRequest request;
508	    request.vendor_id   = m_proposal.vendor_id;
509	    request.model_id    = m_proposal.model_id;
510	    request.variant     = m_proposal.variant;
511	    request.material    = m_proposal.material;
512	    request.name        = m_proposal.model_name;
513	    request.device_id   = m_proposal.device_id;
514	    request.access_code = access_code;
515	
516	    SavedPrinter      added;
517	    const std::string problem = m_backend.add_printer(request, added);
518	    if (!problem.empty()) {
519	        // One error at a time, in the thread, with what to do about it.
520	        m_host.post_note(problem);
521	        m_host.session_changed();
522	        return;
523	    }
524	    m_host.printers_changed();
525	    m_host.close_panel();
526	}
527	
528	void PrinterConversation::use_network_printer(const std::string& device_id)
529	{
530	    refresh_network();
531	    const auto found = std::find_if(m_network.begin(), m_network.end(),
532	                                    [&device_id](const DiscoveredPrinter& printer) { return printer.stable_id == device_id; });
533	    if (found == m_network.end()) {
534	        m_host.post_note("That printer is no longer on the network. Say which printer you have and I will set it up unconnected.");
535	        m_host.session_changed();
536	        return;
537	    }
538	
539	    m_host.post_note("\"Use this\" · " + found->stable_id);
540	
541	    std::ostringstream prompt;
542	    prompt << "The person tapped \"Use this\" on the printer found on the network. It reports itself as model id "
543	           << found->device_model_id << ", name \"" << found->name << "\", serial " << found->stable_id;
544	    if (found->nozzle_diameter > 0.)
545	        prompt << ", a " << nozzle_text(found->nozzle_diameter) << " nozzle";
546	    if (!found->ams_name.empty())
547	        prompt << ", " << found->ams_name << " with " << found->spools.size() << " spools";
548	    prompt << ", over " << (found->connection.empty() ? "the network" : found->connection)
549	           << ". Find that model with printer_catalog_search, propose it with these reported facts as settled rather than assumed, and "
550	              "say that nothing had to be assumed. Then say the person can keep it connected by entering its access code, which is under "
551	              "Settings > Network on the printer.";
552	    m_placeholder = "access code, optional";
553	    m_host.ask_agent(prompt.str());
554	}
555	
556	void PrinterConversation::choose_candidate(const std::string& catalog_id)
557	{
558	    const CatalogPrinter* chosen = catalog_entry(catalog_id);
559	    if (chosen == nullptr)
560	        return;
561	    m_host.ask_agent("The person tapped \"This one\" on " + chosen->vendor_name + " " + chosen->model_name + " (" + chosen->id +
562	                     "). Propose that printer alone with printer_propose and say in one sentence what you assumed.");
563	}
