48	class FakeBackend final : public IPrinterBackend
49	{
50	public:
51	    std::vector<CatalogPrinter>    catalogue{mini(), v2()};
52	    std::vector<DiscoveredPrinter> network;
53	    std::vector<SavedPrinter>      saved;
54	    std::string                    refusal;
55	
56	    std::vector<AddPrinterRequest>    added;
57	    std::vector<ChangePrinterRequest> changed;
58	    int                               manual_setups{0};
59	    std::vector<std::string>          settings_opened;
60	
61	    std::vector<CatalogPrinter> search_catalog(const std::string& text, std::size_t limit) const override
62	    {
63	        searched.push_back(text);
64	        std::vector<CatalogPrinter> found;
65	        for (const CatalogPrinter& printer : catalogue) {
66	            if (found.size() >= limit)
67	                break;
68	            found.push_back(printer);
69	        }
70	        return found;
71	    }
72	    std::vector<DiscoveredPrinter> network_printers() const override { return network; }
73	    std::vector<SavedPrinter>      saved_printers() const override { return saved; }
74	
75	    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& result) override
76	    {
77	        added.push_back(request);
78	        if (!refusal.empty())
79	            return refusal;
80	        result.name = request.name;
81	        return {};
82	    }
83	    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& result) override
84	    {
85	        changed.push_back(request);
86	        if (!refusal.empty())
87	            return refusal;
88	        result = saved.empty() ? SavedPrinter{} : saved.front();
89	        if (request.nozzle)
90	            result.nozzle = *request.nozzle;
91	        return {};
92	    }
93	    void run_manual_setup() override { ++manual_setups; }
94	    void open_printer_settings(const std::string& name) override { settings_opened.push_back(name); }
95	
96	    mutable std::vector<std::string> searched;
97	};
98	
99	class RecordingPanel final : public IConversationHost
100	{
101	public:
102	    std::vector<std::string> notes;
103	    std::vector<std::string> prompts;
104	    int                      states{0};
105	    int                      closes{0};
106	    int                      refreshes{0};
107	
108	    void post_note(const std::string& text) override { notes.push_back(text); }
109	    void ask_agent(const std::string& prompt) override { prompts.push_back(prompt); }
110	    void session_changed() override { ++states; }
111	    void close_panel() override { ++closes; }
112	    void printers_changed() override { ++refreshes; }
113	};
