42	std::string picture_data_url(const std::string& path)
43	{
44	    if (path.empty())
45	        return {};
46	    std::ifstream file(std::filesystem::u8path(path), std::ios::binary);
47	    if (!file.good())
48	        return {};
49	    std::ostringstream bytes;
50	    bytes << file.rdbuf();
51	    const std::string data = bytes.str();
52	    if (data.empty())
53	        return {};
54	    return "data:image/png;base64," + base64_encode(data);
55	}
