58	{
59	    json value{{"value", fact.value}, {"provenance", fact.provenance}};
60	    if (!fact.swatch.empty())
61	        value["swatch"] = fact.swatch;
62	    return value;
63	}
64	
65	// What a printer says it has loaded, as one line: "AMS lite · PLA Matte + 3".
66	std::string spool_summary(const std::string& ams, const std::vector<PrinterSpool>& spools)
67	{
68	    if (spools.empty())
69	        return ams.empty() ? std::string() : ams;
70	    std::string summary = spools.front().name.empty() ? spools.front().material : spools.front().name;
71	    if (spools.size() > 1)
72	        summary += " + " + std::to_string(spools.size() - 1);
73	    return ams.empty() ? summary : ams + " · " + summary;
74	}
