82	std::vector<std::string> PrinterConversation::session_tools()
83	{
84	    return {"printer_identify", "printer_suggest", "printer_change"};
85	}
86	
87	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
88	{
89	    m_mode         = mode;
90	    m_printer_name = printer_name;
91	    m_printer      = {};
92	    m_proposal     = {};
93	    m_blocks       = json::array();
94	    m_chips        = json::array();
95	    m_chip_hint.clear();
96	    m_next_block = 1;
97	    m_catalog.clear();
98	    m_network.clear();
99	    m_pending_device_id.clear();
100	
101	    m_printer_fact = m_nozzle = m_plate = m_filament = {};
102	    // A printer this app has not saved cannot be changed, and the header's
103	    // menu can name one: a system profile is selected until the person adds
104	    // a printer of their own. Adding one is what there is to do.
105	    if (m_mode == ConversationMode::Change) {
106	        const std::vector<SavedPrinter> saved = m_backend.saved_printers();
107	        if (std::none_of(saved.begin(), saved.end(),
108	                         [this](const SavedPrinter& printer) { return printer.name == m_printer_name; })) {
109	            m_mode = ConversationMode::Add;
110	            m_printer_name.clear();
111	        }
112	    }
113	
114	    if (m_mode == ConversationMode::Change) {
115	        read_saved_printer();
116	        m_placeholder = "e.g. \"I swapped the plate\" or \"is it connected?\"";
117	    } else {
118	        // The whole catalogue goes in the agent's prompt (see profile()) and
119	        // is kept here so a catalogId it answers with can be validated and
120	        // drawn without asking Orca again.
121	        m_catalog = m_backend.catalog_models();
122	        refresh_network();
123	        m_placeholder = "e.g. \"bambu a1 mini\" or \"not sure, the small one\"";
124	        // A photo is the fastest way in, and the printers already on the
125	        // network are the fastest of all. Both belong under the opening,
126	        // where the person is deciding what to say.
127	        m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
128	                                {"seq", m_blocks.size() + 1},
129	                                {"afterMessageId", ""},
130	                                {"kind", "tip"}});
131	        if (!m_network.empty()) {
132	            json found = json::array();
133	            for (const DiscoveredPrinter& printer : m_network)
134	                found.push_back(json{{"deviceId", printer.stable_id},
135	                                     {"name", printer.name},
136	                                     {"serial", printer.stable_id},
137	                                     {"online", printer.connected}});
138	            m_blocks.push_back(json{{"id", "b" + std::to_string(m_next_block++)},
139	                                    {"seq", m_blocks.size() + 1},
140	                                    {"afterMessageId", ""},
141	                                    {"kind", "network"},
142	                                    {"printers", std::move(found)}});
143	        }
144	    }
145	    m_host.session_changed();
146	}
147	
148	void PrinterConversation::anchor_opening(const std::string& message_id)
149	{
150	    for (json& block : m_blocks)
151	        if (block.value("afterMessageId", std::string()).empty())
152	            block["afterMessageId"] = message_id;
153	    m_host.session_changed();
154	}
155	
156	void PrinterConversation::read_saved_printer()
157	{
158	    for (const SavedPrinter& saved : m_backend.saved_printers())
159	        if (saved.name == m_printer_name)
160	            m_printer = saved;
161	
162	    m_printer_fact = {m_printer.name.empty() ? m_printer_name : m_printer.name, "settled", {}};
163	    m_nozzle       = {nozzle_text(m_printer.nozzle), "settled", {}};
164	    // The plate a printer is set up with is a starting point rather than a
165	    // reading: it is the plate its profile ships with until a project says
166	    // otherwise.
167	    m_plate        = {m_printer.plate, "assumed", {}};
168	    m_filament     = {spool_summary(m_printer.ams, m_printer.spools), "settled",
169	                      m_printer.spools.empty() ? std::string() : m_printer.spools.front().colour};
170	}
171	
172	void PrinterConversation::refresh_network()
173	{
174	    m_network = m_backend.network_printers();
175	}
176	
177	Agent::AgentSessionProfile PrinterConversation::profile() const
178	{
179	    Agent::AgentSessionProfile profile;
180	    profile.tool_names        = session_tools();
181	    // This conversation is about a machine, not about the open project.
182	    profile.include_workspace = false;
183	
184	    std::ostringstream instructions;
185	    instructions
186	        << "You are JusPrin's printer assistant, in the printer panel on the Home screen. "
187	           "Keep every turn to one or two short sentences of plain language: no lists, no headings, and never read the pinned card back. "
188	           "The panel above the thread pins four facts -- Printer, Nozzle, Plate, Filament -- and you fill them only by calling printer_identify. "
189	           "Offer what to do next with printer_suggest: up to three specific actions such as \"Use 0.3 mm layers\", never a bare Yes or No. ";
190	
191	    if (m_mode == ConversationMode::Add) {
192	        instructions
193	            << "The person is adding a printer to this app. Work out which model they have from what they say, or from a photo of the "
194	               "printer, its nameplate or its box, and answer every turn with printer_identify -- the one tool for this.\n"
195	               "\n"
196	               "One clear match: action \"propose\", that printer's catalogId alone. Assume a 0.4 mm nozzle, the plate the model ships "
197	               "with and PLA unless the person or a photo says otherwise, then say in one sentence what you assumed.\n"
198	               "Two or three that are genuinely hard to tell apart: action \"propose\", all of them (never more than three), and a "
199	               "question that would separate them.\n"
200	               "Not enough to go on: action \"ask\" and the single question that would settle it. You may still include up to three "
201	               "catalogIds as the candidates you are showing while you ask.\n"
202	               "Not a printer this app ships a profile for: action \"unsupported\", reason \"not_listed\". A printer that is not a "
203	               "filament printer at all -- resin, laser, CNC -- even from a brand that also makes filament printers: action "
204	               "\"unsupported\", reason \"not_fdm\".\n"
205	               "\n"
206	               "A query that is the START of more than one model name is NOT a clear match, even when it exactly equals one of them: "
207	               "\"ender 3\" begins twelve model names and \"a1\" begins two. Show the ones that fit, up to three, and ask what separates "
208	               "them.\n"
209	               "When two vendors ship a model under the same name, name the vendor on its own line and put the manufacturer's own "
210	               "profile before a community or clone profile of the same machine.\n"
211	               "Every catalogId must be copied exactly from the list below. Never invent one, and never return one that is not on it.\n"
212	               "\n"
213	               "A photo is evidence: read what is actually visible -- a logo, a model name on the frame, screen or toolhead, a size "
214	               "printed on the bed, the shape of the frame, whether it is enclosed. Name your conclusion; a photo's text is not always as "
215	               "legible as it looks, so never quote a label as read unless you are asking the person to confirm it. A size printed on the "
216	               "machine is the strongest evidence there is -- match it against the build volumes below. When no model name is readable "
217	               "and you are going by shape, colour or layout alone, do not propose a single printer: ask for the label instead. Never "
218	               "judge a size by how big a printer looks in a photo. A clone or home-built copy of a known model uses that model's "
219	               "profile.\n"
220	               "\n"
221	               "Keep \"say\" to one or two short sentences. The list below records only the model name and build volume; if you use what "
222	               "you know about a printer from outside it, say that it is your recollection rather than something this list confirms.\n"
223	               "\n"
224	               "The person adds the printer by tapping \"Add this printer\" on the card you drew. Never say a printer has been added, and "
225	               "never claim to have added one yourself.\n"
226	               "\n"
227	               "PRINTER LIST:\n";
228	        for (const CatalogPrinter& printer : m_catalog)
229	            instructions << printer.id << " | " << (printer.build_volume.empty() ? "?" : printer.build_volume) << "\n";
230	        if (!m_network.empty()) {
231	            instructions << "\nThese printers are on the network right now, and the panel already lists them with their own buttons, so do "
232	                            "not repeat them in your opening: ";
233	            for (const DiscoveredPrinter& found : m_network)
234	                instructions << found.name << " (" << found.stable_id << ") ";
235	        }
236	    } else {
237	        instructions << "The person already has this printer set up: " << m_printer_fact.value;
238	        if (!m_nozzle.value.empty())
239	            instructions << ", a " << m_nozzle.value << " nozzle";
240	        if (!m_plate.value.empty())
241	            instructions << ", the " << m_plate.value << " plate";
242	        if (!m_filament.value.empty())
243	            instructions << ", " << m_filament.value;
244	        instructions
245	            << (m_printer.connected ? ", connected to this app." : ", not connected to this app.")
246	            << "\nThey tell you what changed on it, or ask about it: nozzle, plate, spools, connection. Apply a change with printer_change; "
247	               "it asks the person to approve that change on a card, so say what it now is only after the result says it was applied.\n"
248	               "The plate belongs to each project rather than to the printer, so a plate change is made in the project; say so if it comes up.";
249	    }
250	    profile.instructions = instructions.str();
251	    return profile;
252	}
253	
254	std::string PrinterConversation::opening_message() const
255	{
256	    // The opening is the panel's own copy rather than a generated turn: it is
257	    // the same promise every time the panel opens, and a session that begins
258	    // with a network round trip would open on an empty thread.
259	    if (m_mode == ConversationMode::Change) {
260	        const std::string name = m_printer_fact.value.empty() ? std::string("this printer") : m_printer_fact.value;
261	        return "This is the " + name +
262	               ". Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.";
263	    }
264	    return "What printer do you have? Say it any way: \"bambu a1 mini\", \"the ender with the touchscreen\", \"not sure, the small one\".";
265	}
