289	const CatalogPrinter* PrinterConversation::catalog_entry(const std::string& id) const
290	{
291	    const auto entry = std::find_if(m_catalog.begin(), m_catalog.end(),
292	                                    [&id](const CatalogPrinter& printer) { return printer.id == id; });
293	    return entry == m_catalog.end() ? nullptr : &*entry;
