1	// The printer panel's session: what it states, what its tools do, and what a
2	// tap on one of its cards asks for. The backend and the panel are fakes, so
3	// these are the conversation's own decisions, with no Orca and no model.
4	
5	#include <catch2/catch_all.hpp>
6	
7	#include "slic3r/GUI/JusPrin/Agent/ProjectPersistence.hpp"
8	#include "slic3r/GUI/JusPrin/PrinterSetup/PrinterConversation.hpp"
9	#include "../jusprin_support/FakeWorkspace.hpp"
10	
11	#include <nlohmann/json.hpp>
12	
13	#include <algorithm>
14	
15	using namespace Slic3r::GUI::JusPrin;
16	using namespace Slic3r::GUI::JusPrin::PrinterSetup;
17	using nlohmann::json;
18	
19	namespace {
20	
21	CatalogPrinter mini()
22	{
23	    CatalogPrinter printer;
24	    printer.id               = "BBL/Bambu Lab A1 mini";
25	    printer.vendor_id        = "BBL";
26	    printer.vendor_name      = "Bambu Lab";
27	    printer.model_id         = "Bambu Lab A1 mini";
28	    printer.model_name       = "A1 mini";
29	    printer.device_model_id  = "N1";
30	    printer.build_volume     = "180 × 180 × 180 mm";
31	    printer.default_plate    = "Textured PEI Plate";
32	    printer.default_material = "Bambu PLA Basic @BBL A1M";
33	    printer.nozzles          = {0.2, 0.4, 0.6, 0.8};
34	    return printer;
35	}
36	
37	CatalogPrinter v2()
38	{
39	    CatalogPrinter printer = mini();
40	    printer.id          = "Creality/Ender-3 V2";
41	    printer.vendor_id   = "Creality";
42	    printer.vendor_name = "Creality";
43	    printer.model_id    = "Ender-3 V2";
44	    printer.model_name  = "Ender-3 V2";
45	    return printer;
46	}
47	
48	class FakeBackend final : public IPrinterBackend
49	{
50	public:
51	    std::vector<CatalogPrinter>    catalogue{mini(), v2()};
52	    std::vector<DiscoveredPrinter> network;
53	    std::vector<SavedPrinter>      saved;
54	    std::string                    refusal;
55	
56	    std::vector<AddPrinterRequest>    added;
57	    std::vector<ChangePrinterRequest> changed;
58	    int                               manual_setups{0};
59	    std::vector<std::string>          settings_opened;
60	
61	    std::vector<CatalogPrinter> catalog_models() const override { return catalogue; }
62	    std::vector<DiscoveredPrinter> network_printers() const override { return network; }
63	    std::vector<SavedPrinter>      saved_printers() const override { return saved; }
64	
65	    std::string add_printer(const AddPrinterRequest& request, SavedPrinter& result) override
66	    {
67	        added.push_back(request);
68	        if (!refusal.empty())
69	            return refusal;
70	        result.name = request.name;
71	        return {};
72	    }
73	    std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& result) override
74	    {
75	        changed.push_back(request);
76	        if (!refusal.empty())
77	            return refusal;
78	        result = saved.empty() ? SavedPrinter{} : saved.front();
79	        if (request.nozzle)
80	            result.nozzle = *request.nozzle;
81	        return {};
82	    }
83	    void run_manual_setup() override { ++manual_setups; }
84	    void open_printer_settings(const std::string& name) override { settings_opened.push_back(name); }
85	};
86	
87	class RecordingPanel final : public IConversationHost
88	{
89	public:
90	    std::vector<std::string> notes;
91	    std::vector<std::string> prompts;
92	    int                      states{0};
93	    int                      closes{0};
94	    int                      refreshes{0};
95	
96	    void post_note(const std::string& text) override { notes.push_back(text); }
97	    void ask_agent(const std::string& prompt) override { prompts.push_back(prompt); }
98	    void session_changed() override { ++states; }
99	    void close_panel() override { ++closes; }
100	    void printers_changed() override { ++refreshes; }
101	};
102	
103	// One tool call, as the coordinator would hand it over.
104	Agent::ToolActivity call(Agent::ToolHandler handler, const json& arguments, const std::string& message = "m-1")
105	{
106	    Agent::ToolActivity activity;
107	    activity.correlation_id = message;
108	    activity.arguments_json = arguments.dump();
109	    (void) handler;
110	    return activity;
111	}
112	
113	// A "propose" identify call for one printer, as the agent would send it once
114	// it has settled on a catalogId from the list the session gave it.
115	Agent::ToolExecutionCoordinator::ExtensionResult propose_one(PrinterConversation& conversation, const std::string& catalog_id,
116	                                                              json extra = json::object(), const std::string& message = "m-1")
117	{
118	    json arguments = json{{"action", "propose"}, {"catalogIds", json::array({catalog_id})}, {"say", "Assuming the usual."}};
119	    arguments.update(extra);
120	    return conversation.execute_tool(Agent::ToolHandler::PrinterIdentify,
121	                                     call(Agent::ToolHandler::PrinterIdentify, arguments, message));
122	}
123	
124	DiscoveredPrinter found_a1()
125	{
126	    DiscoveredPrinter printer;
127	    printer.stable_id       = "01P00A3B";
128	    printer.name            = "Bambu Lab A1 mini";
129	    printer.device_model_id = "N1";
130	    printer.connection      = "LAN";
131	    printer.connected       = true;
132	    printer.nozzle_diameter = 0.4;
133	    printer.ams_name        = "AMS lite";
134	    return printer;
135	}
136	
137	} // namespace
138	
139	TEST_CASE("an Add session opens with nothing stated and the ways in", "[printer-conversation]")
140	{
141	    FakeBackend     backend;
142	    RecordingPanel  panel;
143	    backend.network = {found_a1()};
144	    PrinterConversation conversation(backend, panel);
145	    conversation.start(ConversationMode::Add);
146	
147	    const json state = conversation.state_json();
148	    CHECK(state.at("mode") == "add");
149	    CHECK(state.at("caption") == "NEW PRINTER");
150	    for (const char* fact : {"printer", "nozzle", "plate", "filament"})
151	        CHECK(state.at("facts").at(fact).at("value") == "");
152	    CHECK(state.at("placeholder").get<std::string>().find("bambu a1 mini") != std::string::npos);
153	
154	    // The opening says how a photo gets in, and lists what is on the network.
155	    const json& blocks = state.at("blocks");
156	    REQUIRE(blocks.size() == 2);
157	    CHECK(blocks[0].at("kind") == "tip");
158	    CHECK(blocks[1].at("kind") == "network");
