24	function nextClientMessageId(): string {
25	  clientMessageCounter += 1;
26	  return `c-${clientMessageCounter}-${Math.random().toString(36).slice(2, 10)}`;
27	}
28	
29	let clientAttachmentCounter = 0;
30	function nextClientAttachmentId(): string {
31	  clientAttachmentCounter += 1;
32	  return `ca-${clientAttachmentCounter}-${Math.random().toString(36).slice(2, 10)}`;
33	}
34	
35	function readAsDataUrl(file: File): Promise<string> {
36	  return new Promise((resolve, reject) => {
37	    const reader = new FileReader();
38	    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
39	    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
40	    reader.readAsDataURL(file);
41	  });
42	}
43	
44	declare global {
45	  interface Window {
46	    // Deterministic hooks for the native shell harness; harmless in
47	    // production and never a second control path for users.
48	    __jusprinTest?: {
49	      send(text: string): void;
50	      decide(actionId: string, decision: 'approve' | 'reject'): void;
51	      cancelTool(actionId: string): void;
52	      createConversation(): void;
53	      switchConversation(conversationId: string): void;
54	      renameConversation(conversationId: string, title: string): void;
55	      deleteConversation(conversationId: string): void;
56	      setDraft(text: string): void;
57	      openSetup(): void;
58	      checkKey(provider: string, apiKey: string): void;
59	      attach(name: string, dataBase64: string, mime?: string): void;
60	      removeAttachment(attachmentId: string): void;
61	      state(): AgentUiState;
62	    };
63	  }
64	}
65	
66	export interface AppProps {
67	  getTransport: () => Transport | null;
68	  handshakeTimeoutMs?: number;
69	  transportRetryMs?: number;
70	  transportRetryLimit?: number;
71	  draftDebounceMs?: number;
72	  // A throwaway, setup-only instance (e.g. embedded in the Add a printer
73	  // dialog rather than the docked panel): show only the setup sub-component,
74	  // never the conversation header, chat list, or composer around it.
75	  embedded?: boolean;
76	  // The printer panel on Home: the same thread and composer, with the printer
77	  // session's own header, pinned card and chips instead of the project's.
78	  printerPanel?: boolean;
79	}
80	
81	const errorTitles: Partial<Record<ConnectionState, string>> = {
82	  'no-transport': 'The Agent panel has no connection to JusPrin',
83	  timeout: 'The Agent panel could not reach JusPrin',
84	  incompatible: 'This Agent panel does not match this JusPrin build',
85	};
86	
87	export function App({
88	  getTransport,
89	  handshakeTimeoutMs,
90	  transportRetryMs,
91	  transportRetryLimit,
92	  draftDebounceMs,
93	  embedded,
94	  printerPanel,
95	}: AppProps) {
96	  const [state, dispatch] = useReducer(reducer, initialState);
97	  const stateRef = useRef<AgentUiState>(state);
98	  stateRef.current = state;
99	
100	  // Which setup screen the dock is showing. This is page-local on purpose:
101	  // the host cares which credentials it was asked to check, not which panel
102	  // is on screen, so navigating setup costs no bridge traffic.
103	  const [setupScreen, setSetupScreen] = useState<'offer' | 'chooser' | 'apiKey' | 'localTool'>('offer');
104	  const [view, setView] = useState<'chat' | 'list' | 'setup'>('chat');
105	  // The setup card's expansion is a temporary layer over the thread, so it is
106	  // page-local and closes on its own the moment the user does something else.
107	  const [setupExpanded, setSetupExpanded] = useState(false);
108	  // Every way out of this chat closes the card's expansion. Kept explicit
109	  // rather than derived from an effect: an effect on (chat, view) re-ran
110	  // whenever the host resent state and re-closed the card mid-click.
111	  const collapseSetup = () => setSetupExpanded(false);
112	  const [commandError, setCommandError] = useState<string | null>(null);
113	  const setupReturn = useRef<'chat' | 'list'>('chat');
114	  // The one-time confirmation after setup succeeds. The page knows what it
115	  // just submitted, so this needs nothing from the host.
116	  const [connected, setConnected] = useState<{ provider: string; warning?: string } | null>(null);
117	
118	  const client = useMemo(() => {
119	    const created: BridgeClient = new BridgeClient({
120	      getTransport,
121	      handshakeTimeoutMs,
122	      transportRetryMs,
123	      transportRetryLimit,
124	      onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
125	      onEnvelope: (envelope: Envelope) => {
126	        if (envelope.type === 'bridge_error') {
127	          const payload = envelope.payload as { code?: string; message?: string };
128	          setCommandError(payload.message ?? 'The action could not be completed.');
129	          // The host restarts after a reload on its side; if it forgot us,
130	          // simply shake hands again.
131	          if (payload.code === 'handshake_required') created.retry();
132	        }
133	        dispatch({ kind: 'host', envelope });
134	      },
135	    });
136	    return created;
137	    // The transport is fixed for the lifetime of the page.
138	    // eslint-disable-next-line react-hooks/exhaustive-deps
139	  }, []);
140	
141	  useEffect(() => {
142	    client.start();
143	  }, [client]);
144	
145	  useEffect(() => {
146	    applyAppearance(state.appearance);
147	  }, [state.appearance]);
148	
149	  useEffect(() => { setView('chat'); setCommandError(null); }, [state.context?.sessionId]);
150	
151	  useEffect(() => {
152	    if (state.needsResync) {
153	      client.send('state_request', {});
154	      dispatch({ kind: 'resync-requested' });
155	    }
156	  }, [state.needsResync, client]);
157	
158	  // The composer shows staged attachments plus any that failed to attach, so a
159	  // rejection stays visible until the user dismisses it; only staged ones are
160	  // actually sent.
161	  const stagedAttachments = state.attachments.filter(
162	    (attachment) => attachment.state === 'staged' || attachment.state === 'error',
163	  );
164	
165	  const sendMessage = (text: string) => {
166	    // From the ref, not this render: the test hook keeps the first render's
167	    // sendMessage, which would otherwise never see a later attachment.
168	    const attachmentIds = stateRef.current.attachments.filter((a) => a.state === 'staged').map((a) => a.id);
169	    client.send('user_message', { clientMessageId: nextClientMessageId(), text, attachmentIds });
170	  };
171	
172	  const attachFiles = (files: File[], source: AttachmentSource) => {
173	    for (const file of files) {
174	      readAsDataUrl(file)
175	        .then((dataUrl) => {
176	          client.send('attach_file', {
177	            clientAttachmentId: nextClientAttachmentId(),
178	            name: file.name,
179	            mime: file.type,
180	            source,
181	            dataBase64: dataUrl,
182	          });
183	        })
184	        .catch(() => {
185	          // A file the browser could not read never becomes a staged
186	          // attachment; the host only sees files it can decode.
187	        });
188	    }
189	  };
190	
191	  const removeAttachment = (attachmentId: string) => {
192	    client.send('remove_attachment', { attachmentId });
193	  };
194	
195	  const sendToolDecision = (actionId: string, decision: 'approve' | 'reject') => {
196	    client.send('tool_decision', { actionId, decision });
197	  };
198	
199	  const sendToolCancel = (actionId: string) => {
200	    client.send('tool_cancel', { actionId });
201	  };
202	
203	  const checkKey = (provider: string, apiKey: string) => {
204	    client.send('setup_check_key', { provider, apiKey });
205	  };
206	
207	  const cancelCheck = () => {
208	    client.send('setup_cancel', {});
209	  };
210	
211	  // The one way into setup: the dock's own button, and the host when another
212	  // JusPrin surface sends the person here.
213	  const openSetup = () => { setupReturn.current = 'chat'; setSetupScreen('chooser'); setView('setup'); };
214	
215	  useEffect(() => {
216	    if (state.setupRequests > 0) openSetup();
217	  }, [state.setupRequests]);
218	
219	  useEffect(() => {
220	    if (state.setup.phase !== 'verified') return;
221	    // The host installs the verified service right after saying so, so the
222	    // dock is about to become a working chat; carry the confirmation across.
223	    // The key screen stays up until that happens, so the round-trip the check
224	    // measured is actually readable rather than flashing past.
225	    setConnected({ provider: state.setup.provider ?? DEFAULT_PROVIDER, warning: state.setup.warning });
226	    if (state.agentStatus === 'ready') setView('chat');
227	  }, [state.setup.phase, state.setup.provider, state.setup.warning, state.agentStatus]);
228	
229	  useEffect(() => {
230	    // A connected Agent replaces the setup surface entirely; if the dock ever
231	    // returns to being unconfigured it starts from the offer, not mid-flow.
232	    if (state.agentStatus === 'ready') setSetupScreen('offer');
233	  }, [state.agentStatus]);
234	
235	  useEffect(() => {
236	    window.__jusprinTest = {
237	      send: sendMessage,
238	      decide: sendToolDecision,
239	      cancelTool: sendToolCancel,
240	      createConversation: () => client.send('create_conversation', {}),
241	      switchConversation: (conversationId: string) => client.send('switch_conversation', { conversationId }),
242	      renameConversation: (conversationId, title) => client.send('rename_conversation', { conversationId, title }),
243	      deleteConversation: (conversationId) => client.send('delete_conversation', { conversationId }),
244	      setDraft: (text: string) => client.send('draft_update', { text }),
245	      openSetup,
246	      checkKey,
247	      attach: (name: string, dataBase64: string, mime?: string) =>
248	        client.send('attach_file', {
249	          clientAttachmentId: nextClientAttachmentId(),
250	          name,
251	          mime: mime ?? '',
252	          source: 'picker',
253	          dataBase64,
254	        }),
255	      removeAttachment,
256	      state: () => stateRef.current,
257	    };
258	    return () => {
259	      delete window.__jusprinTest;
260	    };
261	    // eslint-disable-next-line react-hooks/exhaustive-deps
262	  }, []);
263	
264	  if (state.connection === 'connecting') return <div className="app"><ConnectingPane /></div>;
265	
266	  if (state.connection !== 'connected') {
267	    return (
268	      <div className="app">
269	        <BridgeErrorPane
270	          title={errorTitles[state.connection] ?? 'The Agent panel could not connect'}
271	          detail={state.connectionDetail}
272	          diagnostics={state.diagnostics}
273	          onRetry={() => client.retry()}
274	        />
275	      </div>
276	    );
277	  }
278	
279	  const unavailable = state.agentStatus === 'unavailable';
280	  // Nothing has been delegated yet, so the dock's whole surface becomes the
281	  // one offer. A conversation carried in from a previously configured session
282	  // keeps its history and gets the banner above it instead.
283	  const notConfigured = unavailable && state.messages.length === 0;
284	  const streaming = state.streamingMessageId !== null;
285	  const busy = streaming || state.conversationBusy;
286	  const activeChat = state.conversations.find((chat) => chat.id === state.activeConversationId);
287	  const externalActions = state.toolActivities.filter((activity) => activity.source === 'mcp' && activity.requiresApproval);
288	  const externalPlans = planMembers(externalActions);
289	  const pendingAction = state.toolActivities.some((activity) =>
290	    state.messages.some((message) => message.id === activity.correlationId) &&
291	    ['pending', 'approved', 'running'].includes(activity.state));
292	  const createChat = () => { client.send('create_conversation', {}); setView('chat'); collapseSetup(); };
293	  const closeSetup = () => { cancelCheck(); setSetupScreen('offer'); setView(setupReturn.current); collapseSetup(); };
294	
295	  const errorNotice = commandError && <div className="chat-error" role="alert">
296	    <span>{commandError}</span><button aria-label="Dismiss error" onClick={() => setCommandError(null)}>×</button>
297	  </div>;
298	
299	  const chatList = <ChatList conversations={state.conversations} activeId={state.activeConversationId} busy={busy}
300	      onSwitch={(conversationId) => {
301	        if (conversationId !== state.activeConversationId) client.send('switch_conversation', { conversationId });
302	        setView('chat');
303	        collapseSetup();
304	      }} onCreate={createChat} onConfigure={() => {
305	        setupReturn.current = 'list'; setSetupScreen('chooser'); setView('setup');
306	      }} />;
307	
308	  // The dock body is one of three things: the conversation, the offer, or a
309	  // setup screen. Setup replaces the body rather than covering it, so backing
310	  // out returns to exactly what was there before.
311	  const body = () => {
312	    // An embedded, setup-only instance never has a conversation to show, so
313	    // it always renders one of the setup screens below regardless of view.
314	    if (!embedded && !notConfigured && view !== 'setup')
315	      return (
316	        <MessageList
317	          dimmed={setupExpanded}
318	          key={`messages-${state.context?.sessionId}-${state.activeConversationId}`}
319	          messages={state.messages}
320	          attachments={state.attachments}
321	          streamingMessageId={state.streamingMessageId}
322	          toolActivities={state.toolActivities}
323	          builds={state.builds}
324	          exportedCopies={state.exportedCopies}
325	          physicalPrints={state.physicalPrints}
326	          changes={state.changes.filter((change) => change.conversationId === state.activeConversationId)}
327	          onRetry={(messageId) => client.send('retry_message', { messageId })}
328	          onToolDecision={sendToolDecision}
329	          onToolCancel={sendToolCancel}
330	        />
331	      );
332	    if (setupScreen === 'chooser')
333	      return <SetupChooser onUseApiKey={() => setSetupScreen('apiKey')} onConnectTool={() => setSetupScreen('localTool')} onDismiss={closeSetup} />;
334	    if (setupScreen === 'localTool')
335	      return (
336	        <SetupLocalTool
337	          catalog={state.mcpCatalog}
338	          preview={state.mcpPreview}
339	          status={state.mcpStatus}
340	          onRefresh={() => client.send('mcp_catalog', {})}
341	          onPreview={(toolId) => client.send('mcp_preview', { toolId })}
342	          onConnect={(toolId) => client.send('mcp_connect', { toolId })}
343	          onReveal={(toolId) => client.send('reveal_path', { toolId })}
344	          onBack={() => setSetupScreen('chooser')}
345	          onDone={closeSetup}
346	        />
347	      );
348	    if (setupScreen === 'apiKey')
349	      return (
350	        <SetupApiKey
351	          setup={state.setup}
352	          onCheck={checkKey}
353	          onCancel={cancelCheck}
354	          onBack={() => {
355	            cancelCheck();
356	            setSetupScreen('chooser');
357	          }}
358	        />
359	      );
360	    return <AgentNotConfiguredPane onSetUp={openSetup} />;
361	  };
362	
363	  if (printerPanel) {
364	    const session = state.session;
365	    const printerAction = (action: string, id = '') => client.send('printer_action', { action, id });
366	    return (
367	      // The whole panel takes a photo, not only the composer: a picture of
368	      // the printer is dropped where the person is looking.
369	      <div
370	        className="app app--printer"
371	        onDragOver={(event) => event.preventDefault()}
372	        onDrop={(event) => {
373	          const files = Array.from(event.dataTransfer.files ?? []);
374	          if (files.length === 0) return;
375	          event.preventDefault();
376	          attachFiles(files, 'drop');
377	        }}
378	      >
379	        {errorNotice}
380	        <div className="chat-content">
381	          {/* The label names where ‹ leads, not the printer this is about. */}
382	          <header className="chat-header printer-header">
383	            <button type="button" className="icon-button" aria-label="Back to printers" onClick={() => printerAction('close')}>
384	              ‹
385	            </button>
386	            <h1>Printers</h1>
387	            <button type="button" className="printer-manual-link" onClick={() => printerAction('manual_setup')}>
388	              Set it up myself
389	            </button>
390	          </header>
391	          {session && !notConfigured && (
392	            <div className="pinned-setup">
393	              <PrinterPinnedCard session={session} />
394	            </div>
395	          )}
396	          {notConfigured ? (
397	            body()
398	          ) : (
399	            <MessageList
400	              messages={state.messages}
401	              attachments={state.attachments}
402	              streamingMessageId={state.streamingMessageId}
403	              // In this panel a tool's result is the card it draws, so only a
404	              // decision to make, or a failure to explain, is worth a row of
405	              // its own beside it.
406	              toolActivities={state.toolActivities.filter(
407	                (activity) => activity.requiresApproval || activity.state === 'failed',
408	              )}
409	              builds={[]}
410	              exportedCopies={[]}
411	              physicalPrints={[]}
412	              changes={[]}
413	              printerBlocks={session?.blocks}
414	              onPrinterAction={(action, id) => printerAction(action, id)}
415	              answeredState={false}
416	              onRetry={(messageId) => client.send('retry_message', { messageId })}
417	              onToolDecision={sendToolDecision}
418	              onToolCancel={sendToolCancel}
419	            />
420	          )}
421	          {!notConfigured && session && (
422	            <PrinterChipRow
423	              chips={session.chips}
424	              hint={session.chipHint}
425	              disabled={busy}
426	              onAdd={() => printerAction('add')}
427	              onSay={sendMessage}
428	            />
429	          )}
430	          {!notConfigured && (
431	            <Composer
432	              disabled={unavailable}
433	              disabledReason={unavailable ? 'The Agent is not available' : undefined}
434	              placeholder={session?.placeholder}
435	              photoButton
436	              streaming={streaming}
437	              attachments={stagedAttachments}
438	              onSend={sendMessage}
439	              onStop={() => {
440	                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
441	              }}
442	              onAttachFiles={attachFiles}
443	              onRemoveAttachment={removeAttachment}
444	            />
445	          )}
446	        </div>
447	      </div>
448	    );
449	  }
450	
451	  if (embedded) {
452	    // No conversation header, chat list, composer, or external-tool banner --
453	    // just the setup sub-component itself, at whatever size its host gives it.
454	    return (
455	      <div className="app app--embedded">
456	        {errorNotice}
457	        <div className="chat-content">{body()}</div>
458	      </div>
459	    );
460	  }
461	
462	  return (
463	    <div className="app">
464	      {errorNotice}
465	      {externalActions.length > 0 && <section className="external-actions" aria-label="External AI tools">
466	        <h2>External AI tools</h2>
467	        {externalActions.map((activity) => {
468	          const key = planKey(activity);
469	          const found = key ? externalPlans.get(key) : undefined;
470	          // A plan of one change is decided like any other call.
471	          const members = found && found.length > 1 ? found : undefined;
472	          if (members && members[0].actionId !== activity.actionId) return null;
473	          return members
474	            ? <PlanActivityCard key={activity.actionId} members={members} headline={planHeadline(state.toolActivities)}
475	                onDecision={sendToolDecision} onCancel={sendToolCancel} />
476	            : <ToolActivityCard key={activity.actionId} activity={activity}
477	                onDecision={sendToolDecision} onCancel={sendToolCancel} />;
478	        })}
479	      </section>}
480	      {view === 'list' && chatList}
481	      <div className="chat-content" hidden={view === 'list'}>
482	      {notConfigured && state.conversations.length === 1 && view !== 'setup' ? (
483	        <AgentNotConfiguredHeader />
484	      ) : (
485	        <>
486	          <ChatHeader key={`header-${state.context?.sessionId}-${state.activeConversationId}`} title={activeChat?.title || 'New chat'} busy={busy || pendingAction}
487	            onBack={() => { collapseSetup(); if (view === 'setup') closeSetup(); else { client.send('state_request', {}); setView('list'); } }}
488	            onCreate={createChat}
489	            onRename={(title) => client.send('rename_conversation', { conversationId: state.activeConversationId, title })}
490	            onDelete={() => { client.send('delete_conversation', { conversationId: state.activeConversationId }); setView('list'); }} />
491	          {view === 'chat' && !notConfigured && state.context && (
492	            // The card sits in its own pinned band above the thread, as the
493	            // design has it: the band is the canvas the tinted card sits on.
494	            <div className="pinned-setup">
495	              <SetupCard context={state.context} expanded={setupExpanded} working={busy}
496	                onToggle={() => setSetupExpanded((open) => !open)} />
497	            </div>
498	          )}
499	        </>
500	      )}
501	      {unavailable && !notConfigured && <AgentUnavailableNotice />}
502	      {!notConfigured && connected && (
503	        <ConnectedBanner
504	          provider={connected.provider}
505	          warning={connected.warning}
506	          onDismiss={() => setConnected(null)}
507	        />
508	      )}
509	      {body()}
510	      <div hidden={view === 'setup'}><Composer
511	        key={`composer-${state.context?.sessionId}-${state.activeConversationId}`}
512	        disabled={unavailable}
513	        disabledReason={notConfigured ? 'ask, or steer this chat…' : unavailable ? 'The Agent is not available' : undefined}
514	        streaming={streaming}
515	        initialText={state.draft}
516	        attachments={stagedAttachments}
517	        onSend={sendMessage}
518	        onStop={() => {
519	          if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
520	        }}
521	        onAttachFiles={attachFiles}
522	        onRemoveAttachment={removeAttachment}
523	        onTyping={collapseSetup}
524	        onDraftChange={(text) => client.send('draft_update', { text })}
525	        draftDebounceMs={draftDebounceMs}
526	      /></div>
527	      </div>
528	    </div>
529	  );
530	}
