content.content:
1	// The printer panel's own parts: the card pinned above the thread, the cards
2	// the agent draws inside it, and the row of things to tap.
3	//
4	// Everything here renders host state. A tap either sends a typed printer
5	// action, which C++ carries out, or sends the chip's own words as the
6	// person's message -- never both, and never a change made on this side.
7	
8	import { memo } from 'react';
9	import type {
10	  NetworkPrinterInfo,
11	  PrinterBlock,
12	  PrinterCardInfo,
13	  PrinterChip,
14	  PrinterFact,
15	  PrinterSessionPayload,
16	} from '../bridge/protocol';
17	
18	const EM_DASH = '—';
19	
20	function factClass(fact: PrinterFact): string {
21	  if (!fact.value) return 'printer-fact-value printer-fact-empty';
22	  return `printer-fact-value printer-fact-${fact.provenance}`;
23	}
24	
25	function factSuffix(fact: PrinterFact): string {
26	  if (!fact.value) return '';
27	  if (fact.provenance === 'assumed') return ' · assumed';
28	  if (fact.provenance === 'changed') return ' · changed';
29	  return '';
30	}
31	
32	function FactRow({ label, fact }: { label: string; fact: PrinterFact }) {
33	  return (
34	    <div className="printer-fact">
35	      <span className="printer-fact-label">{label}</span>
36	      <span className={factClass(fact)}>
37	        {fact.swatch && <span className="printer-swatch" style={{ background: fact.swatch }} aria-hidden="true" />}
38	        {fact.value || EM_DASH}
39	        {factSuffix(fact)}
40	      </span>
41	    </div>
42	  );
43	}
44	
45	// The four facts a printer is, in the order the panel always states them.
46	export const PrinterPinnedCard = memo(function PrinterPinnedCard({ session }: { session: PrinterSessionPayload }) {
47	  return (
48	    <section className="printer-pinned" aria-label={session.caption}>
49	      <p className="printer-pinned-caption">{session.caption}</p>
50	      <FactRow label="Printer" fact={session.facts.printer} />
51	      <FactRow label="Nozzle" fact={session.facts.nozzle} />
52	      <FactRow label="Plate" fact={session.facts.plate} />
53	      <FactRow label="Filament" fact={session.facts.filament} />
54	    </section>
55	  );
56	});
57	
58	// The camera the panel shows wherever a photo is offered. Inline, like the
59	// composer's send arrow, because the icon set carries no camera yet.
60	export function CameraGlyph({ className }: { className: string }) {
61	  return (
62	    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
63	      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
64	      <circle cx="12" cy="13" r="4" />
65	    </svg>
66	  );
67	}
68	
69	export interface PrinterBlockProps {
70	  block: PrinterBlock;
71	  onAction: (action: 'network_pick' | 'candidate_pick' | 'add', id: string) => void;
72	}
73	
74	// One card the agent drew, in the thread, under the message that drew it.
75	export const PrinterBlockView = memo(function PrinterBlockView({ block, onAction }: PrinterBlockProps) {
76	  if (block.kind === 'tip')
77	    return (
78	      <div className="printer-tip">
79	        <CameraGlyph className="printer-tip-icon" />
80	        <span>
81	          <b>Tip:</b> a photo is the fastest way. Use <b>Photo</b> below, or drop a picture of the printer, its nameplate or the box
82	          into this panel.
83	        </span>
84	      </div>
85	    );
86	
87	  if (block.kind === 'network') {
88	    const found = (block.printers ?? []) as NetworkPrinterInfo[];
89	    return (
90	      <div className="printer-found">
