/* One clear match: the card owns its own "Add this printer", bottom right,
   stacked under the picture and name rather than beside them. */
.printer-cards-wrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.printer-card-propose {
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
}

.printer-card-top {
  display: flex;
  align-items: center;
  gap: 12px;
}

.printer-card-add {
  align-self: flex-end;
  padding: var(--button-primary-padding, var(--button-secondary-padding));
  border: 1px solid var(--action-primary);
  border-radius: var(--radius-standard);
  background: var(--action-primary);
  cursor: pointer;
  font: var(--font-label-bold);
  color: var(--action-primary-text);
}

.printer-card-add:hover {
  background: var(--action-primary-hover);
  border-color: var(--action-primary-hover);
}

/* A quiet line under the card, not a docked chip: rejecting is never the
   same weight as adding. */
.printer-reject-line {
  align-self: flex-start;
  border: none;
  background: none;
  padding: 0;
  cursor: pointer;
  font: var(--font-label);
  color: var(--text-secondary);
}

.printer-reject-line:hover {
  color: var(--text-primary);
}

/* Superseded or rejected: one grey line, no button, no picture. */
.printer-cards-collapsed {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.printer-card-collapsed {
  font: var(--font-label);
  color: var(--text-tertiary);
}

/* Not a printer this app ships a profile for: the panel's own way out,
   never only the agent's wording. */
.printer-exit {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-container);
  background: var(--surface-raised);
  overflow: hidden;
}

.printer-exit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  border: none;
  border-bottom: 1px solid var(--border-subtle);
  background: none;
  cursor: pointer;
  text-align: left;
  font: var(--font-label-bold);
  color: var(--text-primary);
}

