1	// Conversation transcript with stable scroll anchoring: the list follows new
2	// content only while the reader is at the bottom; scrolling up to reread
3	// pins the viewport until they return to the bottom. Tool activity cards
4	// render beneath the assistant message that proposed them, a plan's calls as
5	// one card beneath the message that proposed its first call; the change log and
6	// the manufacturing history render after the conversation item they follow,
7	// in the order they happened.
8	
9	import { Fragment, useLayoutEffect, useRef, useState } from 'react';
10	import {
11	  AttachmentInfo,
12	  BuildInfo,
13	  ChangeInfo,
14	  ExportedCopyInfo,
15	  PhysicalPrintInfo,
16	  PrinterBlock,
17	  ToolActivityInfo,
18	} from '../bridge/protocol';
19	import { Message } from '../state/store';
20	import { AttachmentChip } from './AttachmentChip';
21	import { ChangeRows } from './ChangeRows';
22	import { MarkdownMessage } from './MarkdownMessage';
23	import { ToolActivityCard } from './ToolActivityCard';
24	import { PlanActivityCard, planHeadline, planKey, planMembers } from './PlanActivityCard';
25	import { ManufacturingHistoryCard, ManufacturingHistoryEntry } from './ManufacturingHistoryCard';
26	import { PrinterBlockView } from './PrinterPanel';
27	
28	interface Props {
29	  messages: Message[];
30	  attachments: AttachmentInfo[];
31	  streamingMessageId: string | null;
32	  toolActivities: ToolActivityInfo[];
33	  builds: BuildInfo[];
34	  exportedCopies: ExportedCopyInfo[];
35	  physicalPrints: PhysicalPrintInfo[];
36	  changes: ChangeInfo[]; // already filtered to this conversation
37	  onRetry: (messageId: string) => void;
38	  onToolDecision: (actionId: string, decision: 'approve' | 'reject') => void;
39	  onToolCancel: (actionId: string) => void;
40	  // The setup card's expansion is a layer over this thread; the thread dims
41	  // rather than being covered, so the conversation stays legibly there.
42	  dimmed?: boolean;
43	  // The printer panel's own cards, each anchored after the message that drew
44	  // it, the way history entries are. Absent everywhere else.
45	  printerBlocks?: PrinterBlock[];
46	  onPrinterAction?: (
47	    action: 'network_pick' | 'candidate_pick' | 'add' | 'reject' | 'browse' | 'manual_setup',
48	    id: string,
49	  ) => void;
50	  // "Answered · nothing changed" is about the open project, which the printer
51	  // panel is not having a conversation about.
52	  answeredState?: boolean;
53	}
54	
55	// What follows one conversation item: history cards and runs of changes, in
56	// seq order. Consecutive changes form one block, which draws as one group.
57	type TimelineBlock =
58	  | { kind: 'history'; seq: number; entry: ManufacturingHistoryEntry }
59	  | { kind: 'changes'; seq: number; changes: ChangeInfo[] };
60	
61	function timeline(history: ManufacturingHistoryEntry[], changes: ChangeInfo[]): TimelineBlock[] {
62	  const items = [
63	    ...history.map((entry) => ({ seq: entry.seq, history: entry, change: undefined })),
64	    ...changes.map((change) => ({ seq: change.seq, history: undefined, change })),
65	  ].sort((a, b) => a.seq - b.seq);
66	  const blocks: TimelineBlock[] = [];
67	  for (const item of items) {
68	    const previous = blocks[blocks.length - 1];
69	    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
70	    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
71	    else blocks.push({ kind: 'history', seq: item.seq, entry: item.history! });
72	  }
73	  return blocks;
74	}
75	
76	function TimelineBlocks({ blocks }: { blocks: TimelineBlock[] }) {
77	  return (
78	    <>
79	      {blocks.map((block) =>
80	        block.kind === 'history' ? (
81	          <ManufacturingHistoryCard key={`${block.entry.kind}-${block.entry.record.id}`} entry={block.entry} />
82	        ) : (
83	          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} />
84	        ),
85	      )}
86	    </>
87	  );
88	}
89	
90	const inFlight = new Set(['pending', 'approved', 'running']);
91	
92	export function MessageList({
93	  messages,
94	  attachments,
95	  streamingMessageId,
96	  toolActivities,
97	  builds,
98	  exportedCopies,
99	  physicalPrints,
100	  changes,
101	  onRetry,
102	  onToolDecision,
103	  onToolCancel,
104	  dimmed,
105	  printerBlocks = [],
106	  onPrinterAction,
107	  answeredState = true,
108	}: Props) {
109	  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
110	  const listRef = useRef<HTMLDivElement>(null);
111	  const [followBottom, setFollowBottom] = useState(true);
112	
113	  const handleScroll = () => {
114	    const list = listRef.current;
115	    if (!list) return;
116	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
117	    setFollowBottom(distanceFromBottom < 24);
118	  };
119	
120	  useLayoutEffect(() => {
121	    const list = listRef.current;
122	    if (list && followBottom) list.scrollTop = list.scrollHeight;
123	  }, [messages, toolActivities, builds, exportedCopies, physicalPrints, changes, printerBlocks, followBottom]);
124	
125	  const history: ManufacturingHistoryEntry[] = [
126	    ...builds.map((record) => ({ kind: 'build' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
127	    ...exportedCopies.map((record) => ({ kind: 'copy' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
128	    ...physicalPrints.map((record) => ({ kind: 'print' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
129	  ];
130	  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
131	  const plans = planMembers(toolActivities);
132	  const headline = planHeadline(toolActivities);
133	  // A change follows a message or one of its tool activities; both place it
134	  // after that message's group.
135	  const messageOfItem = new Map<string, string>();
136	  for (const message of messages) {
137	    messageOfItem.set(message.id, message.id);
138	    for (const activity of activitiesOf(message.id)) messageOfItem.set(activity.actionId, message.id);
139	  }
140	  const changesAfter = (messageId: string) => changes.filter((change) => messageOfItem.get(change.afterId) === messageId);
141	  const leadingChanges = changes.filter((change) => !messageOfItem.has(change.afterId));
142	  const historyAfter = (messageId: string) => history.filter((entry) => entry.afterMessageId === messageId);
143	  const printerBlocksAfter = (messageId: string) =>
144	    printerBlocks.filter((block) => block.afterMessageId === messageId).sort((a, b) => a.seq - b.seq);
145	  const printerBlockViews = (messageId: string) =>
146	    onPrinterAction
147	      ? printerBlocksAfter(messageId).map((block) => (
148	          <PrinterBlockView key={block.id} block={block} onAction={onPrinterAction} />
149	        ))
150	      : null;
151	  const leadingHistory = history.filter(
152	    (entry) => entry.afterMessageId === '' || !messages.some((message) => message.id === entry.afterMessageId),
153	  );
154	
155	  // A finished reply that changed nothing says so (Figma "Answered
156	  // response"). Only the Agent's own changes count against it; the person
157	  // editing by hand while it answered is not the Agent changing something.
158	  const answeredWithoutChange = (message: Message) =>
159	    answeredState &&
160	    message.role === 'assistant' &&
161	    message.state === 'complete' &&
162	    message.id !== streamingMessageId &&
163	    !activitiesOf(message.id).some((activity) => inFlight.has(activity.state)) &&
164	    !changesAfter(message.id).some((change) => change.actor === 'agent');
165	
166	  return (
167	    <div className={dimmed ? 'message-list thread-dimmed' : 'message-list'} role="log" aria-label="Agent conversation"
168	      ref={listRef} onScroll={handleScroll}>
169	      <TimelineBlocks blocks={timeline(leadingHistory, leadingChanges)} />
170	      {messages.length === 0 && (
171	        <div className="notice">
172	          <h2>Ask the Agent about your print</h2>
173	          <p>
174	            The Agent can describe the open project, the plates and objects on them, the current selection, and the
175	            printer setup — or duplicate the selected object with your approval.
176	          </p>
177	        </div>
178	      )}
179	      {messages.map((message) => {
180	        if (message.role === 'note')
181	          return (
182	            <div key={message.id} className="message-group">
183	              <div className="message note" role="status">
184	                {message.text}
185	              </div>
186	            </div>
187	          );
188	        const bubble = (
189	          <div className={`message ${message.role}`}>
190	            {/* The agent does not speak in a bubble: a 20px action/primary
191	                disc stands beside plain text, as the Figma "Chat Bubble"
192	                component's Agent variant has it. Purely decorative -- the
193	                author is already carried by the role class and by the
194	                bubble the user's turn keeps. */}
195	            {message.role === 'assistant' && <span className="agent-avatar" aria-hidden="true" />}
196	            <div className="message-content">
197	              {message.text &&
198	                (message.role === 'assistant' ? (
199	                  <MarkdownMessage streaming={message.id === streamingMessageId}>{message.text}</MarkdownMessage>
200	                ) : (
201	                  <span>{message.text}</span>
202	                ))}
203	              {message.attachments && message.attachments.length > 0 && (
204	                <div className="message-attachments">
205	                  {message.attachments.map((id) => {
206	                    const attachment = attachmentsById.get(id);
207	                    return attachment ? <AttachmentChip key={id} attachment={attachment} /> : null;
208	                  })}
209	                </div>
210	              )}
211	              {message.state === 'failed' && message.error && (
212	                <div className="error">
213	                  {message.error.message}
214	                  {message.error.retryable && (
215	                    <div>
216	                      <button onClick={() => onRetry(message.id)}>Retry</button>
217	                    </div>
218	                  )}
219	                </div>
220	              )}
221	              {message.state === 'stopped' && <div className="meta">Stopped</div>}
222	            </div>
223	          </div>
224	        );
225	        // The message group is one thread item: the turn and the tool cards
226	        // it proposed, 8 apart. What follows it -- change runs and history
227	        // entries -- are thread items of their own.
228	        return (
229	          <Fragment key={message.id}>
230	            <div className="message-group">
231	              {answeredWithoutChange(message) ? (
232	                <div className="answered-turn">
233	                  {bubble}
234	                  <div className="answered-state">Answered · nothing changed</div>
235	                </div>
236	              ) : (
237	                bubble
238	              )}
239	              {activitiesOf(message.id).map((activity) => {
240	                const key = planKey(activity);
241	                const found = key ? plans.get(key) : undefined;
242	                // A plan of one change is decided like any other call, once
243	                // the agent can no longer add to it.
244	                const members = found && (found.length > 1 || streamingMessageId !== null) ? found : undefined;
245	                if (members && members[0].actionId !== activity.actionId) return null;
246	                return members ? (
247	                  <PlanActivityCard
248	                    key={activity.actionId}
249	                    members={members}
250	                    headline={headline}
251	                    stillProposing={streamingMessageId !== null}
252	                    onDecision={onToolDecision}
253	                    onCancel={onToolCancel}
254	                  />
255	                ) : (
256	                  <ToolActivityCard
257	                    key={activity.actionId}
258	                    activity={activity}
259	                    onDecision={onToolDecision}
260	                    onCancel={onToolCancel}
261	                  />
262	                );
263	              })}
264	            </div>
265	            {printerBlockViews(message.id)}
266	            <TimelineBlocks blocks={timeline(historyAfter(message.id), changesAfter(message.id))} />
267	          </Fragment>
268	        );
269	      })}
270	    </div>
271	  );
272	}
