1	// What the printer panel states and what a tap on it does. The panel renders
2	// host state and sends typed actions; nothing here decides a printer fact on
3	// its own, so these tests pin the reading and the sending, not a model.
4	
5	import { describe, expect, it, vi } from 'vitest';
6	import { render, screen } from '@testing-library/react';
7	import userEvent from '@testing-library/user-event';
8	import type { PrinterBlock, PrinterChip, PrinterSessionPayload } from '../bridge/protocol';
9	import { PrinterBlockView, PrinterChipRow, PrinterPinnedCard } from './PrinterPanel';
10	
11	function session(overrides: Partial<PrinterSessionPayload> = {}): PrinterSessionPayload {
12	  return {
13	    mode: 'add',
14	    caption: 'NEW PRINTER',
15	    facts: {
16	      printer: { value: '', provenance: 'settled' },
17	      nozzle: { value: '', provenance: 'settled' },
18	      plate: { value: '', provenance: 'settled' },
19	      filament: { value: '', provenance: 'settled' },
20	    },
21	    blocks: [],
22	    chips: [],
23	    chipHint: '',
24	    placeholder: 'e.g. "bambu a1 mini" or "not sure, the small one"',
25	    ...overrides,
26	  };
27	}
28	
29	describe('the pinned card', () => {
30	  it('states the four facts in order, with an em dash for what nobody has said', () => {
