    const onSay = vi.fn();
    render(<PrinterChipRow chips={chips} hint="or just type" disabled={false} onSay={onSay} />);

    await userEvent.click(screen.getByRole('button', { name: 'Use 0.3 mm layers' }));
    expect(onSay).toHaveBeenCalledWith('Use 0.3 mm layers');
